<template>
  <section class="time-admin"><header class="section-row"><h2>每日投入</h2><strong>{{ formatMinutes(total) }}</strong></header><p class="muted">按分钟填写；保存后会同步到记录日历和关于页。</p><form @submit.prevent="save"><div class="field date-field"><label for="time-log-date">日期</label><input id="time-log-date" v-model="date" type="date" :max="today" required :disabled="saving" /></div><p v-if="loading" role="status">加载中…</p><template v-else><div v-for="(entry, index) in entries" :key="entry.key" class="time-admin-row"><div class="field"><label :for="`time-category-${entry.key}`">投入项目</label><input :id="`time-category-${entry.key}`" v-model.trim="entry.category" maxlength="80" list="time-categories" required :disabled="saving || !!loadError" /></div><div class="field"><label :for="`time-minutes-${entry.key}`">分钟</label><input :id="`time-minutes-${entry.key}`" v-model.number="entry.minutes" type="number" min="1" max="1440" step="1" required :disabled="saving || !!loadError" /></div><button class="secondary-button" type="button" :aria-label="`移除第 ${index + 1} 个项目`" :disabled="saving || !!loadError" @click="entries.splice(index, 1)">移除</button></div><datalist id="time-categories"><option v-for="name in suggestions" :key="name" :value="name" /></datalist><div class="time-admin-actions"><button class="secondary-button" type="button" :disabled="saving || !!loadError || entries.length >= 30" @click="add">添加项目</button><button class="primary-button" :disabled="saving || !!loadError || total > 1440">{{ saving ? '保存中…' : '保存当天记录' }}</button><button class="danger-button" type="button" :disabled="saving || !!loadError || !exists" @click="remove">删除当天记录</button></div></template><p v-if="loadError" class="error-text" role="alert">{{ loadError }} <button class="text-button" type="button" @click="load">重试</button></p><p v-if="total > 1440" class="error-text" role="alert">每日总时长不能超过 24 小时。</p><p v-if="notice" :class="success ? 'success-text' : 'error-text'" role="status">{{ notice }}</p></form></section>
</template>
<script setup>
import { computed, ref, watch } from 'vue';
import { getAdminTimeLog, saveTimeLog, deleteTimeLog } from '../../api/activity';
import { apiError, formatMinutes, todayISO } from '../../utils/format';
const today = todayISO(), date = ref(today), entries = ref([]), loading = ref(true), saving = ref(false), exists = ref(false), notice = ref(''), success = ref(false), loadError = ref('');
const suggestions = ['C++', '数据结构', '英语', '阅读', '运动'];
const total = computed(() => entries.value.reduce((n, entry) => n + (Number(entry.minutes) || 0), 0));
let sequence = 0, loadId = 0;
function add() { entries.value.push({ key: ++sequence, category: '', minutes: 30 }); }
async function load() { const id = ++loadId; if (!date.value) { loadError.value = '请选择日期。'; loading.value = false; return; } loading.value = true; notice.value = ''; loadError.value = ''; try { const { data } = await getAdminTimeLog(date.value); if (id !== loadId) return; entries.value = data.entries.map((entry) => ({ ...entry, key: ++sequence })); exists.value = data.entries.length > 0; if (!entries.value.length) add(); } catch (error) { if (id === loadId) loadError.value = apiError(error, '记录加载失败，请重试后再编辑。'); } finally { if (id === loadId) loading.value = false; } }
async function save() { saving.value = true; notice.value = ''; try { const { data } = await saveTimeLog(date.value, { entries: entries.value.map(({ category, minutes }) => ({ category, minutes: Number(minutes) })) }); exists.value = data.entries.length > 0; notice.value = '当天记录已保存。'; success.value = true; } catch (error) { success.value = false; notice.value = apiError(error); } finally { saving.value = false; } }
async function remove() { if (!window.confirm(`删除 ${date.value} 的投入记录？`)) return; saving.value = true; try { await deleteTimeLog(date.value); entries.value = []; add(); exists.value = false; success.value = true; notice.value = '当天记录已删除。'; } catch (error) { success.value = false; notice.value = apiError(error); } finally { saving.value = false; } }
watch(date, load, { immediate: true });
</script>
<style scoped>
.time-admin{display:grid;gap:20px}.time-admin h2{font-size:25px;font-weight:500}.time-admin form{display:grid;gap:18px}.date-field{max-width:260px}.time-admin-row{display:grid;grid-template-columns:minmax(0,1fr) 130px auto;gap:14px;align-items:end}.time-admin-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:8px}@media(max-width:560px){.time-admin-row{grid-template-columns:minmax(0,1fr) 85px;gap:10px}.time-admin-row>button{grid-column:1/-1;justify-self:start}.time-admin-actions{align-items:stretch;flex-direction:column}}
</style>
